/// Layer 2 of three: the evaluated scene (docs/v3/04 §5).
library;

import '../core/core.dart' hide Animation;
import 'package:flutter/foundation.dart';
import 'package:flutter/rendering.dart';

import 'group_clip.dart';
import 'paint_translation.dart';
import 'path_geometry.dart';
import 'render_faults.dart';

/// Draws an **already-evaluated** [Scene].
///
/// Top-level and free of `CustomPainter`, `Size` and `BuildContext` on purpose:
/// this is the function the golden tests call with a hand-built `Scene`, and
/// every one of the interesting failure modes (degenerate path, unknown paint
/// source, collapsed matrix) is reachable from a three-line test rather than
/// from a pumped widget.
///
/// Every **coordinate** comes from the [Scene] and the [document] supplies
/// exactly one thing: **hierarchy**, for `clipChildren` (AC-2.1.6). A clip
/// applies to a subtree, and `drawOrder` is flat — it carries the groups, but
/// nothing in it says where a group's subtree ends. That is the same split
/// [hitTestScene] and [selectionBounds] already make, and it is *not* the
/// second evaluator docs/v3/08 §4 names: no position, opacity or visibility is
/// re-derived here, so there is nothing this walk could disagree with
/// `composeWorldA` about. A painter that read the document to decide *what to
/// draw* would be, and the symptom would be "the canvas is right until you
/// scrub".
///
/// [fit] is the document→screen transform, normally [artboardFit]. It is a
/// parameter rather than something computed here because hit-testing must
/// invert the *same* matrix; computing the fit twice is how a click lands where
/// the shape is not.
void paintScene(
  Canvas canvas,
  Scene scene,
  Document document, {
  Affine fit = Affine.identity,
}) {
  final base = canvas.getSaveCount();
  canvas.save();
  canvas.transform(affineToMatrix4(fit));

  // Built after the fit is on the canvas, so a group's window is placed by the
  // very matrix its geometry is drawn through.
  final clips = GroupClipStack.forCanvas(canvas, document, scene);

  // The guard is INSIDE the loop, never around it (docs/v3/08 §1). One bad
  // node vanishes; the other 113 render. A try around the whole loop is the
  // same defect as legacy's per-frame modal wearing a quieter coat: it erases
  // the artboard the user needs in order to recover from the bug.
  for (final node in scene.drawOrder) {
    try {
      clips.enter(canvas, node.path);
      _drawNode(canvas, node);
    } catch (error, stack) {
      // A throw between `save` and `restore` leaves the canvas transformed —
      // or worse, CLIPPED — for every subsequent node, so the failure would
      // smear across nodes that are individually fine. Unwinding to the
      // stack's floor drops everything this item leaked while keeping the
      // clips its ancestors legitimately opened, which is what keeps "one node
      // vanishes" literally true.
      canvas.restoreToCount(clips.floor);
      final watched = RenderFaults.report(RenderFault(
        stage: 'drawNode',
        path: node.path,
        error: error,
        stack: stack,
      ));
      assert(watched, 'anim_render: unreported paint fault on ${node.path}');
    }
  }

  // Closes the fit save and any clip still open, in one call: a group whose
  // subtree ends the document has nothing after it to close it.
  canvas.restoreToCount(base);
}

void _drawNode(Canvas canvas, ResolvedNode node) {
  // `worldVisible` already ANDs every ancestor and `worldOpacity` already
  // multiplies them (docs/v3/01 §3). Re-deriving either here would be the
  // second evaluator.
  if (!node.worldVisible) return;
  if (!(node.worldOpacity > 0)) return; // also rejects NaN, unlike `<= 0`

  final geometry = node.geometry;
  if (geometry == null) return; // a group, or a node type this build shrugs at

  // A collapsed matrix draws nothing and never throws. The evaluator is total
  // (docs/v3/01 §1 rule 3) and the renderer must not reintroduce the crash the
  // evaluator was built to prevent — so this is an early return, never
  // `invert()!` (docs/v3/08 §4, the recurring five). `isPlaceable` is the
  // package's one definition of "this matrix can be drawn through": the overlay
  // and the selection bounds ask the same question and must not answer it
  // differently.
  if (!isPlaceable(node.world)) return;

  if (node.fills.isEmpty && node.strokes.isEmpty) return;

  final path = buildPath(geometry); // 0 or 1 anchor yields an empty ui.Path

  canvas.save();
  canvas.transform(affineToMatrix4(node.world));

  for (final fill in node.fills) {
    if (!fill.visible) continue;
    final paint = paintFor(fill.paint, node.worldOpacity * fill.opacity);
    if (paint == null) continue; // unknown source: preserved on disk, not drawn
    paint
      ..style = PaintingStyle.fill
      ..blendMode = BlendMode.srcOver;
    path.fillType = toUiFillType(fill.rule);
    canvas.drawPath(path, paint);
  }

  // Strokes paint after every fill, always. The order is fixed rather than
  // authorable because per-item z-order between fills and strokes is a feature
  // nobody asked for and a diff nobody can review.
  for (final stroke in node.strokes) {
    if (!stroke.visible) continue;
    final paint = paintFor(stroke.paint, node.worldOpacity * stroke.opacity);
    if (paint == null) continue;
    paint
      ..style = PaintingStyle.stroke
      ..strokeWidth = stroke.width
      ..strokeCap = toUiCap(stroke.cap)
      ..strokeJoin = toUiJoin(stroke.join)
      ..strokeMiterLimit = stroke.miterLimit;
    canvas.drawPath(path, paint);
  }

  canvas.restore();
}

/// The `CustomPainter` that owns layer 2.
///
/// **The playhead never enters `build()`.** It arrives as a `ValueNotifier`
/// handed to `super(repaint:)`, so a tick calls `paint()` directly and rebuilds
/// no widget at all. Routing it through a provider instead is a named
/// antipattern (docs/v3/08 §4): it couples every panel to the frame budget, and
/// one slow inspector makes scrubbing unusable app-wide. Legacy round-tripped
/// the playhead through pixels and a `BuildContext`; this constructor is the
/// structural reason that cannot happen again.
///
/// [evaluate] runs **inside** `paint()`. That is what keeps the tick out of the
/// widget tree, and at the docs/v3/00 §6 budget (114 anchors × 10 keyframes) a
/// full pass is free. The `Scene` and the `PathData → ui.Path` conversion are
/// deliberately **not** cached: a cache keyed on mutable geometry is a
/// stale-render bug that looks exactly like an evaluator bug, and it costs days
/// in the wrong package (docs/v3/08 §4).
class ArtboardPainter extends CustomPainter {
  ArtboardPainter({
    required this.document,
    required this.playhead,
    required this.animation,
    required this.fit,
    required this.mode,
  }) : super(repaint: playhead);

  final Document document;

  /// The composed `viewport ∘ artboardFit` the canvas built once (docs/v3/05 §3).
  ///
  /// **Required, and never null.** It used to be optional, with each of the
  /// three painters falling back to its own `artboardFit(...)` — three sites
  /// that could each build a document→screen mapping, so a caller that passed
  /// `fit:` to two of them and forgot the third got one silently un-panned layer
  /// with no compile error and no failing test. One mapping, one source: the
  /// canvas computes `composedFit` once, hands the *result* to all three
  /// painters, and inverts that same result for hit-testing (AC-3.1.4).
  final Affine fit;

  /// Editor or export preview — the one thing that decides whether the board
  /// clips (AC-1.1.3). See [RenderMode]; the rect itself comes from
  /// [artboardClipRect], which the overlay reads too.
  final RenderMode mode;

  /// Identity is stable for the app's lifetime; only its value changes.
  final ValueNotifier<double> playhead;

  /// Which animation the playhead is a position *within*.
  ///
  /// Null renders the rest pose, which is a defined result and not an edge
  /// case: `evaluate(doc, const [])` is how a document with no animation draws
  /// (docs/v3/01 §11).
  final AnimationId? animation;

  @override
  void paint(Canvas canvas, Size size) {
    final anim = animation;
    final mix = anim == null
        ? const <AnimationMix>[]
        : <AnimationMix>[AnimationMix(anim, _clampT(playhead.value))];

    final scene = evaluate(document, mix);

    // **The editor does not clip** (AC-1.1.3): off-artboard geometry is legal,
    // it draws, and it is selectable. Clipping it here while `hitTestScene`
    // clips nothing and the overlay clips nothing is how a user ends up with a
    // selection box and anchor handles floating over blank canvas around a
    // shape they cannot see and can still drag. The export preview *does* clip,
    // because there the board is the frame — one rect, from
    // [artboardClipRect], shared with the overlay.
    //
    // A clipping **group** is a different question and is not conflated with
    // this one: `clipChildren` is authored content, so it is honoured in BOTH
    // modes, inside [paintScene], against the group's own window
    // ([groupClipWindow]) rather than against the board.
    final clip = artboardClipRect(mode, document.artboard, fit);
    if (clip == null) {
      paintScene(canvas, scene, document, fit: fit);
      return;
    }
    canvas.save();
    canvas.clipRect(clip);
    paintScene(canvas, scene, document, fit: fit);
    canvas.restore();
  }

  /// The painter boundary is where a bad playhead stops.
  ///
  /// `TypedTrack.bracket` is honest about NaN — it produces a NaN `u` and
  /// therefore NaN geometry — because clamping inside the evaluator would be a
  /// NaN rescue, which docs/v3/08 §1 forbids. Guards belong out here instead,
  /// at the layer that has a frame to draw and a user to show it to.
  static double _clampT(double t) => t.isNaN ? 0.0 : t.clamp(0.0, 1.0);

  /// Identity, never deep equality.
  ///
  /// [Document] is immutable, so a new object *is* the change signal.
  /// Deep-comparing 114 anchors every frame to avoid a paint that costs less
  /// than the comparison is backwards (docs/v3/04 §5). The playhead is absent
  /// from this test on purpose: it repaints through `super(repaint:)` without a
  /// rebuild, so it can never reach here.
  @override
  bool shouldRepaint(ArtboardPainter old) =>
      !identical(old.document, document) ||
      !identical(old.playhead, playhead) ||
      old.animation != animation ||
      old.mode != mode || // editor ↔ export preview changes the clip
      old.fit != fit; // a pan/zoom repaints the scene without a document change
}

src/render/group_clip.dart:
/// `GroupNode.clipChildren` — AC-2.1.6, in ONE place (docs/v3/04 §5).
///
/// Clipping is hierarchical and `Scene.drawOrder` is flat, so this file is the
/// join between the two. Both painters that can clip read it, for the same
/// reason both read [artboardClipRect]: three hand-rolled clips is the same
/// defect as three hand-rolled fits, one layer down.
library;

import 'dart:ui' as ui;

import '../core/core.dart';

import 'path_geometry.dart';

/// The window a clipping group confines its subtree to, in the group's **own
/// local space**.
///
/// ### The ruling, written down because the model cannot express the ideal
///
/// AC-2.1.6 says a child that "overflows its bounds" is clipped, so the group
/// needs *bounds of its own*. v3's `GroupNode` has `children` and
/// `clipChildren` and **no extent field** — no width/height, no rect. That
/// leaves exactly two candidate definitions:
///
///  1. **The union of its descendants' bounds.** Rejected: it is by
///     construction big enough to contain every descendant, so a clipping group
///     defined this way can never clip anything and the feature means nothing.
///     Every bounds-from-content definition has this property, at every depth.
///  2. **A frame the group carries independently of its content**, placed by
///     the group's own transform. The only extent this document model expresses
///     is `Document.artboard`, and the root of the tree *is* a `GroupNode`
///     whose extent is exactly the artboard (docs/v3/01 §3, "Container. Also
///     the artboard root."). So: **a clipping group's bounds are the artboard
///     rect in the group's own local space.**
///
/// That is After Effects' precomp rule — a precomp layer clips to the *comp's*
/// size, transformed by the layer's transform, not to the size of what is
/// inside it — and it is the closest thing to Figma's "clip content" a frame
/// with no width/height of its own can mean. The group's `Transform2` positions
/// and sizes the window: `position` moves it, `scale` resizes it, `rotation`
/// turns it (the window is clipped in local space, so a rotated group has a
/// rotated window, not an inflated upright one).
///
/// **What an author consequently cannot do yet:** give a group a window whose
/// size or aspect differs from the artboard *without also transforming its
/// children*, because the one matrix does both. A 100 × 50 window needs
/// `GroupNode` to carry its own rect — a field in `anim_core`, the file format
/// and the decoder, which is out of this package's reach. Until it exists,
/// authoring a clip window is authoring a group transform.
///
/// An artboard that is non-positive or non-finite yields [ui.Rect.zero]: a
/// frame with no area shows nothing. Failing closed is the honest reading of
/// "clip to this" — and it keeps a NaN out of `Canvas.clipRect`, which would
/// poison the layer rather than the node.
ui.Rect groupClipWindow(Vec2 artboard) {
  if (!artboard.x.isFinite || !artboard.y.isFinite) return ui.Rect.zero;
  if (artboard.x <= 0 || artboard.y <= 0) return ui.Rect.zero;
  return ui.Rect.fromLTWH(0, 0, artboard.x, artboard.y);
}

/// Every node confined by at least one clipping group → the groups that confine
/// it, **outermost first**. Nodes under no clip are absent, so an ordinary
/// document yields an empty map and costs the painters one `isEmpty` check.
///
/// A clipping group is **not** in its own chain: its clip opens at its first
/// child, not at its own slot. In the GEOMETRY layer a group draws nothing from
/// its own slot (groups have null geometry), so opening the clip there or at the
/// first child records the identical `clipRect`s — nothing is drawn between the
/// two points, so no `clipRect` that wraps a child moves. The OVERLAY is where
/// the difference is load-bearing: the group's own slot draws its selection
/// outline, stroked from the full descendant union ([selectionBounds]), and that
/// union routinely OVERFLOWS the group's artboard-sized window. Opening the
/// group's own clip before that draw truncated the outline — and, when the union
/// enclosed the window on every side, erased it entirely — while [hitTestScene]
/// still answered a click for the whole untruncated union. So the group's own
/// draw stays unclipped by its own window, and every descendant still enters it.
///
/// **The root is never a clipping group, whatever it is authored as.** The
/// artboard boundary belongs to [RenderMode] and to AC-1.1.3 alone: the editor
/// does not clip there, and honouring `root.clipChildren` would silently make
/// it, which is exactly the conflation of "the artboard clip" with "a clipping
/// group" that must not happen. The root is not a node the user selects, drags
/// or hit-tests either (see [hitTestScene]); this is the same exclusion.
///
/// Hierarchy comes from [doc] and every coordinate comes from the `Scene` — the
/// split [selectionBounds] and [hitTestScene] already make. Reading topology
/// here is not a second evaluator: nothing is re-derived, and there is no
/// second traversal that could disagree with `composeWorldA` about a position,
/// because this walk produces no positions. Rebuilt per paint and **never
/// cached** (docs/v3/08 §4).
Map<NodeId, List<NodeId>> clipChains(Document doc) {
  final out = <NodeId, List<NodeId>>{};
  _chain(doc.root, const <NodeId>[], out, isRoot: true);
  return out;
}

void _chain(
  Node node,
  List<NodeId> enclosing,
  Map<NodeId, List<NodeId>> out, {
  bool isRoot = false,
}) {
  // The node's OWN entry is the windows it is inside — its enclosing clips, and
  // never its own. A clipping group is confined by its ancestors, not by its own
  // window: its own-slot draw (nothing in the geometry layer; the selection
  // outline in the overlay) must be unclipped by the window it opens for its
  // children, or the outline of a selected clipping group is truncated to — and
  // often erased by — its own artboard-sized frame.
  if (enclosing.isNotEmpty) out[node.id] = enclosing;

  var confining = enclosing;
  if (!isRoot && node is GroupNode && node.clipChildren) {
    confining = List<NodeId>.unmodifiable(<NodeId>[...enclosing, node.id]);
  }
  if (node is GroupNode) {
    for (final child in node.children) {
      _chain(child, confining, out);
    }
  }
}

/// The clips a painter currently has open, as it walks the flat `drawOrder`.
///
/// `Scene.drawOrder` is a faithful pre-order flattening, but a flat list cannot
/// say where a subtree *ends* — `ScenePath` carries no depth and a group's
/// `ResolvedNode` carries no extent. So membership comes from [clipChains]
/// (topology, from the `Document`) and the window's placement comes from the
/// group's evaluated `world` (coordinates, from the `Scene`).
///
/// Every clip is one `save()`, closed with `restoreToCount`. The stack records
/// the save count taken **before** each `save()`, so [floor] can name the depth
/// a failed item must unwind to: everything that item leaked, and nothing its
/// ancestors legitimately opened. An unbalanced save here would leak a clip
/// into the *next* node, which is invisible on the node that caused it.
final class GroupClipStack {
  GroupClipStack._(
    this._chains,
    this._scene,
    this._window,
    this._base,
    this._floor,
  );

  /// Reads the save count [canvas] is at **now** as the floor, so it must be
  /// built after the caller has pushed whatever state wraps the whole layer
  /// (the fit transform, the export-preview artboard clip).
  ///
  /// [base] maps document space to the canvas's *current* space: identity when
  /// the caller has already applied the fit to the canvas (the geometry layer),
  /// the fit itself when it has not (the overlay draws in screen space).
  factory GroupClipStack.forCanvas(
    ui.Canvas canvas,
    Document document,
    Scene scene, {
    Affine base = Affine.identity,
  }) =>
      GroupClipStack._(
        clipChains(document),
        scene,
        groupClipWindow(document.artboard),
        base,
        canvas.getSaveCount(),
      );

  final Map<NodeId, List<NodeId>> _chains;
  final Scene _scene;
  final ui.Rect _window;
  final Affine _base;
  final int _floor;

  final List<NodeId> _open = <NodeId>[];
  final List<int> _depths = <int>[];

  /// The save count an item that threw must be unwound to.
  int get floor => _depths.isEmpty ? _floor : _depths.last + 1;

  /// True when this document has no clipping group at all — the common case,
  /// and then [enter] never touches the canvas.
  bool get isEmpty => _chains.isEmpty;

  /// Makes the canvas's open clips exactly the chain confining [path]: closes
  /// the ones it has left, opens the ones it has entered, leaves the shared
  /// prefix alone. Closing on the way out is what stops a group's clip leaking
  /// onto the sibling painted after it.
  void enter(ui.Canvas canvas, ScenePath path) {
    final chain = _chains[path.nodeId] ?? const <NodeId>[];

    var shared = 0;
    while (shared < _open.length &&
        shared < chain.length &&
        _open[shared] == chain[shared]) {
      shared++;
    }
    while (_open.length > shared) {
      _open.removeLast();
      canvas.restoreToCount(_depths.removeLast());
    }

    for (var k = shared; k < chain.length; k++) {
      final depth = canvas.getSaveCount();
      canvas.save();
      // Recorded only once the clip is actually applied: if `_apply` throws,
      // `floor` still names the depth below this save, so the item's catch
      // unwinds it and the stack stays honest about what is open.
      _apply(canvas, _scene.byPath[ScenePath(chain[k])]?.world);
      _depths.add(depth);
      _open.add(chain[k]);
    }
  }

  /// Closes every open clip. The layer's own `restore` would do it, but the
  /// overlay keeps drawing after the node loop and its pending markers are tool
  /// state, not document content — they are not inside anybody's group.
  void closeAll(ui.Canvas canvas) {
    _open.clear();
    while (_depths.isNotEmpty) {
      canvas.restoreToCount(_depths.removeLast());
    }
  }

  /// Clips to [world]'s window, leaving the canvas in the space it was in.
  ///
  /// The window is rectangular in the group's **local** space, so it is clipped
  /// there and the matrix is then undone — a group with rotation or skew gets
  /// its real slanted window rather than the upright box around it.
  void _apply(ui.Canvas canvas, Affine? world) {
    // A group whose matrix collapsed (an animator keyed scale to 0) has a
    // window of no area, so its subtree shows nothing. Fail CLOSED: the author
    // asked for the content to be confined, and an unplaceable window confines
    // it to nothing. Never `invert()!` (docs/v3/08 §4).
    if (world == null) {
      canvas.clipRect(ui.Rect.zero);
      return;
    }
    final toCanvas = _base.mul(world);
    final back = toCanvas.invert();
    if (back == null || !isPlaceable(toCanvas)) {
      canvas.clipRect(ui.Rect.zero);
      return;
    }
    canvas.transform(affineToMatrix4(toCanvas));
    canvas.clipRect(_window);
    canvas.transform(affineToMatrix4(back));
  }
}

src/render/paint_translation.dart:
/// Authored paint (`anim_core`) → `dart:ui` paint (docs/v3/04 §5).
///
/// One direction, one file. Every painter in this package goes through these
/// functions rather than building a `Paint` inline, because the moment two call
/// sites translate `Rgba` themselves they disagree about premultiplication and
/// the disagreement shows up as a gradient that is subtly darker than the solid
/// fill beside it.
library;

import 'dart:ui' as ui;

// `StrokeCap`/`StrokeJoin` exist in both worlds with the same names and
// different meanings: ours is authored data, dart:ui's is a paint setting. The
// hide-plus-alias keeps both spellable, so the switches below read as the
// translation they are rather than as a cast.
import '../core/core.dart' hide Animation, StrokeCap, StrokeJoin;
import '../core/core.dart' as anim;
import 'package:flutter/rendering.dart';

/// Straight (non-premultiplied) sRGB doubles in, Flutter [Color] out.
///
/// NaN maps to 0 rather than propagating: this is the painter boundary, where
/// guards are legal (docs/v3/08 §1), and `Color.fromARGB` on a NaN `round()`
/// throws — which would turn one bad stop into a dead frame.
Color toUiColor(Rgba c, double opacity) => Color.fromARGB(
      (_clamp01(c.a * opacity) * 255).round(),
      (_clamp01(c.r) * 255).round(),
      (_clamp01(c.g) * 255).round(),
      (_clamp01(c.b) * 255).round(),
    );

double _clamp01(double v) => v.isNaN ? 0.0 : v.clamp(0.0, 1.0);

/// Null for a paint source this build does not understand.
///
/// The caller skips the draw while the encoder still writes the source back
/// verbatim — that asymmetry is the whole point of [UnknownPaint]. Returning a
/// magenta "error" fill instead would make a document authored by a newer build
/// look corrupt rather than look unsupported.
Paint? paintFor(PaintSource source, double opacity) {
  switch (source) {
    case SolidPaint():
      return Paint()..color = toUiColor(source.color, opacity);
    case LinearGradientPaint():
      if (source.stops.isEmpty) return null;
      return Paint()
        ..shader = ui.Gradient.linear(
          Offset(source.start.x, source.start.y),
          Offset(source.end.x, source.end.y),
          [for (final s in source.stops) toUiColor(s.color, opacity)],
          [for (final s in source.stops) s.offset],
        );
    case RadialGradientPaint():
      if (source.stops.isEmpty || source.radius <= 0) return null;
      return Paint()
        ..shader = ui.Gradient.radial(
          Offset(source.center.x, source.center.y),
          source.radius,
          [for (final s in source.stops) toUiColor(s.color, opacity)],
          [for (final s in source.stops) s.offset],
        );
    case UnknownPaint():
      return null;
  }
}

StrokeCap toUiCap(anim.StrokeCap cap) => switch (cap) {
      anim.StrokeCap.butt => StrokeCap.butt,
      anim.StrokeCap.round => StrokeCap.round,
      anim.StrokeCap.square => StrokeCap.square,
    };

StrokeJoin toUiJoin(anim.StrokeJoin join) => switch (join) {
      anim.StrokeJoin.miter => StrokeJoin.miter,
      anim.StrokeJoin.round => StrokeJoin.round,
      anim.StrokeJoin.bevel => StrokeJoin.bevel,
    };

PathFillType toUiFillType(FillRule rule) => switch (rule) {
      FillRule.nonZero => PathFillType.nonZero,
      FillRule.evenOdd => PathFillType.evenOdd,
    };

src/render/path_geometry.dart:
/// `PathData` → `dart:ui.Path` (docs/v3/04 §5).
library;

import 'dart:math' as math;
import 'dart:typed_data';
import 'dart:ui' as ui;

import '../core/core.dart';

/// Builds the `ui.Path` for one node's geometry.
///
/// Every segment is emitted as a cubic, with no polyline branch: a `corner`
/// anchor has zero tangents, so `cubicTo` collapses to a straight line on its
/// own. Legacy carried separate straight/curve paths that disagreed about
/// where a segment ended.
///
/// Total by construction — a degenerate path yields an empty `ui.Path` rather
/// than throwing, because the pen tool produces exactly that on its first
/// click and a half-drawn shape must not take the canvas down.
ui.Path buildPath(PathData data) {
  final path = ui.Path();
  final anchors = data.anchors;
  if (anchors.length < 2) return path;

  path.moveTo(anchors.first.position.x, anchors.first.position.y);
  for (var k = 0; k < data.segmentCount; k++) {
    final (_, p1, p2, p3) = data.segment(k);
    path.cubicTo(p1.x, p1.y, p2.x, p2.y, p3.x, p3.y);
  }
  if (data.closed) path.close();
  return path;
}

/// The document→screen transform: letterbox the artboard into [size].
///
/// **One uniform factor, never one per axis.** Legacy scaled Y by the width
/// ratio, which is invisible on a square board and drifts on every other one.
///
/// Returned as an [Affine] rather than applied directly to a canvas so that the
/// painter and the editor's hit-testing use the *same* mapping — computing the
/// fit twice is how a click lands somewhere the shape is not.
Affine artboardFit(Vec2 artboard, ui.Size size) {
  if (artboard.x <= 0 || artboard.y <= 0) return Affine.identity;
  final scale = math.min(size.width / artboard.x, size.height / artboard.y);
  return Affine.translate(
    (size.width - artboard.x * scale) / 2,
    (size.height - artboard.y * scale) / 2,
  ).mul(Affine.scale(scale, scale));
}

/// The **whole** document→screen mapping: the editor's pan/zoom [viewport]
/// composed over [artboardFit] (owner decision, docs/v3/05 §3).
///
/// **This is the one and only place the two matrices are combined** (AC-3.1.4).
/// The canvas computes it once per frame, hands the *result* to all three
/// painters as their `fit`, and inverts the *same* result for hit-testing —
/// so a click, the geometry it lands on, and the board it lands over are all
/// governed by a single `Affine`. Composing viewport∘fit a second time
/// somewhere else is exactly how a click lands where the shape is not, and a
/// per-axis scale helper on top of it is the legacy y-scaled-by-width bug
/// (docs/v3/08 §4). `viewport` is identity by default, so the default result is
/// a plain letterbox.
///
/// `mul` is `this ∘ o` (apply `o` first): [artboardFit] maps document→fitted
/// screen, then [viewport] pans/zooms within that fitted screen.
Affine composedFit(Affine viewport, Vec2 artboard, ui.Size size) =>
    viewport.mul(artboardFit(artboard, size));

/// Who the canvas is being drawn for, and therefore whether the board clips.
///
/// AC-1.1.3 is explicit: a node outside the artboard **draws**, is selectable,
/// "and is clipped only at the artboard boundary in the export preview". An
/// editor that clips unconditionally is the defect this enum exists to name —
/// [hitTestScene] applies no clip and the overlay draws none either, so a
/// clipped geometry layer leaves the user a selection box and anchor handles
/// floating over blank canvas around a shape they cannot see but can still
/// click and drag.
enum RenderMode {
  /// The editor: nothing is clipped, so what the user can click is what the
  /// user can see.
  editor,

  /// The export preview: the artboard **is** the frame, so geometry stops at
  /// its edge — the same rect the exporter will encode.
  exportPreview,
}

/// The rect the artboard clips to under [mode], or null when nothing clips.
///
/// One definition, read by every painter that can clip, so the board, the
/// geometry and the overlay can never disagree about where the edge is — three
/// hand-rolled clips is the same defect as three hand-rolled fits, one layer
/// down. Computed in **screen** space because the composed fit is
/// translate + uniform-scale only (a pan/zoom adds no rotation), so the board's
/// rect maps to a rect exactly.
ui.Rect? artboardClipRect(RenderMode mode, Vec2 artboard, Affine fit) {
  if (mode == RenderMode.editor) return null;
  final origin = fit.apply(Vec2.zero);
  final corner = fit.apply(artboard);
  return ui.Rect.fromPoints(
    ui.Offset(origin.x, origin.y),
    ui.Offset(corner.x, corner.y),
  );
}

/// The **world-space** box a node occupies for selection, or null when it
/// encloses nothing.
///
/// For a path node this is the axis-aligned bound of its posed anchors *after*
/// the node's world matrix. For a **group** — which has no geometry of its own
/// — it is the union of its visible descendants' boxes. Without that a group is
/// second-class on the canvas: never hit-testable, and selected from the layers
/// panel with no outline to show for it, which is an odd result for a milestone
/// whose point is that the document is a real tree.
///
/// [hitTestScene] and the overlay's selection outline both read this **one**
/// function, so the box the user sees is exactly the area that answers a click.
/// Two independent bounds is how an outline ends up somewhere the node is not.
///
/// Hierarchy comes from [doc] (topology) and every coordinate comes from
/// [scene] (evaluated) — reading positions off the document here would be the
/// second evaluator docs/v3/08 §4 names. Recomputed on demand and **never
/// cached**: a stored AABB beside mutable geometry is the stale derived state
/// the same section forbids.
ui.Rect? selectionBounds(Scene scene, Document doc, ScenePath path) {
  final node = scene.byPath[path];
  if (node == null) return null; // resolved, never repaired: undo deleted it

  final geometry = node.geometry;
  if (geometry != null) return _geometryBounds(node, geometry);

  final subtree = doc.nodeIndex[path.nodeId];
  if (subtree == null) return null;

  ui.Rect? union;
  for (final descendant in _subtree(subtree)) {
    if (descendant.id == path.nodeId) continue;
    final resolved = scene.byPath[ScenePath(descendant.id)];
    if (resolved == null) continue;
    // A hidden descendant draws nothing, so it contributes no area to click:
    // otherwise the group's box would cover blank canvas.
    if (!resolved.worldVisible) continue;
    final childGeometry = resolved.geometry;
    if (childGeometry == null) continue; // a nested group: its children answer
    final box = _geometryBounds(resolved, childGeometry);
    if (box == null) continue;
    union = union == null ? box : union.expandToInclude(box);
  }
  return union;
}

/// The AABB of [geometry] posed by [node]'s world matrix, or null when it
/// cannot be placed.
///
/// Sampled from the anchor positions — enough for M2's straight-edged shapes;
/// curve-tight bounds are an M3 refinement and would only ever shrink the box,
/// never move what it encloses.
ui.Rect? _geometryBounds(ResolvedNode node, PathData geometry) {
  if (!isPlaceable(node.world)) return null;
  double? minX, minY, maxX, maxY;
  for (final a in geometry.anchors) {
    final w = node.world.apply(a.position);
    if (!w.x.isFinite || !w.y.isFinite) continue;
    minX = (minX == null || w.x < minX) ? w.x : minX;
    minY = (minY == null || w.y < minY) ? w.y : minY;
    maxX = (maxX == null || w.x > maxX) ? w.x : maxX;
    maxY = (maxY == null || w.y > maxY) ? w.y : maxY;
  }
  if (minX == null || minY == null || maxX == null || maxY == null) return null;
  return ui.Rect.fromLTRB(minX, minY, maxX, maxY);
}

Iterable<Node> _subtree(Node node) sync* {
  yield node;
  if (node is GroupNode) {
    for (final child in node.children) {
      yield* _subtree(child);
    }
  }
}

/// True when [m] maps area to area and carries no NaN.
///
/// [Affine.invert] alone is not enough: its singularity test is
/// `determinant.abs() < 1e-12`, and every comparison against NaN is false, so a
/// matrix full of NaNs inverts "successfully" into more NaNs. `Canvas.transform`
/// with a NaN then poisons the whole layer, not just this node.
bool isPlaceable(Affine m) =>
    m.a.isFinite &&
    m.b.isFinite &&
    m.c.isFinite &&
    m.d.isFinite &&
    m.tx.isFinite &&
    m.ty.isFinite &&
    m.invert() != null;

/// The front-most node in [scene] whose posed geometry contains [docPoint], or
/// null on empty space (docs/v3/05 §3, the Select tool).
///
/// **Front-most wins** — the walk is `drawOrder.reversed`, so the last-painted
/// (top) node is tested first, matching what the user sees. **Locked and hidden
/// nodes are not hit** (AC-2.2.6): `worldVisible` is checked here, and the
/// caller supplies [isHittable] to exclude locked nodes (locked is a hit gate,
/// not a render gate, so it is not on `ResolvedNode` — docs/v3/01 §3). The point
/// is taken to node-local space through the node's **own inverted world**, the
/// very matrix the painter used, so the hit region is the pixels that were
/// drawn. A singular world (an animator keyed scale to 0) inverts to null and is
/// skipped — an early return, never `invert()!` (docs/v3/08 §4).
///
/// **A group is hittable too**, over the [selectionBounds] union of its
/// descendants — the same box the overlay outlines. Because `composeWorldA`
/// emits a group *before* its children, the reversed walk tests children first,
/// so a click on a child selects the child and only the gaps between them fall
/// through to the group. [doc] supplies that hierarchy, and it is also what
/// excludes the **root**: the root is the canvas itself, not a node the user
/// may select or drag.
///
/// `AnchorId`s are never consulted, so a synthetic-anchor trim result (M6) is
/// harmless: this tests the *filled region*, not the handles.
ScenePath? hitTestScene(
  Scene scene,
  Document doc,
  Vec2 docPoint,
  bool Function(ScenePath) isHittable,
) {
  final point = ui.Offset(docPoint.x, docPoint.y);
  for (final node in scene.drawOrder.reversed) {
    if (!node.worldVisible) continue;
    if (node.path.nodeId == doc.root.id) continue; // the root is not a node
    if (!isHittable(node.path)) continue; // locked: gated by the caller

    final geometry = node.geometry;
    if (geometry == null) {
      // A group: no fill of its own, so its hit area is the box the user sees
      // when it is selected. Null (an empty or fully hidden group) is nothing
      // to hit, which is honest — there is nothing on screen either.
      final bounds = selectionBounds(scene, doc, node.path);
      if (bounds != null && bounds.contains(point)) return node.path;
      continue;
    }

    final inverse = node.world.invert();
    if (inverse == null) continue; // collapsed: nothing to hit
    final local = inverse.apply(docPoint);
    if (buildPath(geometry).contains(ui.Offset(local.x, local.y))) {
      return node.path;
    }
  }
  return null;
}

/// Where a pen click would split a node's posed outline — the mid-segment
/// insert of docs/v3/05 §3 and AC-4.3.1.
///
/// [after] is the **left** anchor of the hit segment (the `after:` argument
/// `PathOps.insertAnchor` splices behind, respecting the closed wrap) and [u] is
/// the parameter on that segment's cubic, already clamped into the open interval
/// `(0,1)` the op requires. [local] is the projected point in the node's own
/// space; [world] is the same point through the node's world matrix, for the
/// screen-distance gate and the overlay `+`.
class PathInsertHit {
  const PathInsertHit({
    required this.after,
    required this.u,
    required this.local,
    required this.world,
  });

  final AnchorId after;
  final double u;
  final Vec2 local;
  final Vec2 world;
}

/// The nearest mid-segment insertion on [nodeId]'s **posed** geometry to
/// [docPoint], or null when the node has no path, no segment, or a collapsed
/// world.
///
/// The geometry is stages **1–3** (`composeWorldA(resolvePose(sampleTracks…))`),
/// exactly what the overlay draws and the direct-select hit-test grabs — strictly
/// pre-trim, so every `AnchorId` here is the authored one and [PathInsertHit.after]
/// is an id `PathOps.insertAnchor` will find in the topology (stage 7's synthetic
/// trim ids never reach this). The point is taken to node-local space through the
/// node's **own inverted world** — the same matrix the painter used — then
/// projected onto each cubic.
///
/// A pure read: it evaluates a frame and returns a candidate, mutating nothing.
PathInsertHit? insertionCandidate(
  Document doc,
  List<AnimationMix> mix,
  NodeId nodeId,
  Vec2 docPoint,
) {
  final frame = composeWorldA(resolvePose(sampleTracks(doc, mix)));
  for (final node in frame.nodes) {
    if (node.path.nodeId != nodeId) continue;
    final geometry = node.geometry;
    if (geometry == null || geometry.segmentCount == 0) return null;
    // Early return, never `invert()!` (docs/v3/08 §4): a node keyed to a
    // collapsed scale has nowhere on the artboard a click could land.
    final worldToLocal = node.world.invert();
    if (worldToLocal == null) return null;
    final local = worldToLocal.apply(docPoint);

    AnchorId? bestAfter;
    var bestU = 0.5;
    var bestPoint = Vec2.zero;
    var bestDist = double.infinity;
    for (var k = 0; k < geometry.segmentCount; k++) {
      final (p0, p1, p2, p3) = geometry.segment(k);
      final (u, point) = _projectOntoCubic(p0, p1, p2, p3, local);
      final dx = point.x - local.x;
      final dy = point.y - local.y;
      final dist = dx * dx + dy * dy;
      if (dist < bestDist) {
        bestDist = dist;
        bestAfter = geometry.anchors[k].id;
        bestU = u;
        bestPoint = point;
      }
    }
    if (bestAfter == null) return null;
    return PathInsertHit(
      after: bestAfter,
      u: bestU,
      local: bestPoint,
      world: node.world.apply(bestPoint),
    );
  }
  return null;
}

/// Samples for the coarse nearest-point pass. A cubic's foot-of-perpendicular
/// solve is a quintic in `u` with up to three stationary points, so a dense
/// sweep brackets **every** local minimum *before* Newton refines it — Newton
/// alone slides into whichever root it started next to.
///
/// Dense enough (was 24) that a self-crossing cubic whose two branches fold to
/// within a few px still lands one sample on each: at 48, adjacent samples are
/// ~1/48 of the arc apart, so two feet that close resolve to two separate
/// coarse minima rather than merging into one and hiding a branch.
const int _insertSamples = 48;

/// `u` is kept strictly inside `(0,1)`; `PathOps.insertAnchor` refuses the
/// endpoints (they are existing anchors, not a split).
const double _insertMinU = 1e-6;

/// The parameter and point on the cubic `[p0,p1,p2,p3]` nearest to [q].
///
/// **Every** local minimum of `|B(u)-q|²` is refined, not just the one nearest
/// coarse sample. The old single-bracket solve found one minimum and Newton'd
/// from it, which is correct on a convex/monotone cubic — but a cubic can fold so
/// two of its branches pass within ~3 px of each other (a loop drawn with strong
/// opposing tangents), and then the true foot can sit on the branch the single
/// bracket did *not* cover: measured up to 2.63 px along the curve onto the wrong
/// branch. So the coarse sweep keeps every sample that is a local min of squared
/// distance, a few Newton steps on `d/du |B(u)-q|²` — **clamped to that sample's
/// bracket** so refinement never leaves the neighbourhood the sweep chose —
/// polish each, and the global best is returned. Still accurate to machine
/// precision for a query exactly on the curve (a single minimum), the case the
/// insert test asserts on; cheap enough for a hover frame (a fixed sweep and one
/// short Newton per local min, of which a cubic has at most three).
(double, Vec2) _projectOntoCubic(Vec2 p0, Vec2 p1, Vec2 p2, Vec2 p3, Vec2 q) {
  double squaredDist(double u) {
    final b = _cubicAt(p0, p1, p2, p3, u);
    final dx = b.x - q.x;
    final dy = b.y - q.y;
    return dx * dx + dy * dy;
  }

  // Coarse sweep: squared distance at every sample, kept so each interior point
  // can be tested against both neighbours for a local minimum.
  final dist = List<double>.generate(
      _insertSamples + 1, (i) => squaredDist(i / _insertSamples),
      growable: false);

  const step = 1.0 / _insertSamples;
  var bestU = 0.0;
  var bestDist = double.infinity;
  for (var i = 0; i <= _insertSamples; i++) {
    // A local minimum of the coarse samples (endpoints compare only inward).
    // `<=` so a flat run still yields a seed; the global sample-min always
    // qualifies, so there is always at least one candidate to refine.
    final downLeft = i == 0 || dist[i] <= dist[i - 1];
    final downRight = i == _insertSamples || dist[i] <= dist[i + 1];
    if (!(downLeft && downRight)) continue;

    final seed = i * step;
    final lo = (seed - step).clamp(0.0, 1.0);
    final hi = (seed + step).clamp(0.0, 1.0);
    var u = seed;
    for (var iter = 0; iter < 16; iter++) {
      final b = _cubicAt(p0, p1, p2, p3, u);
      final d1 = _cubicDeriv(p0, p1, p2, p3, u);
      final d2 = _cubicDeriv2(p0, p1, p2, p3, u);
      final ex = b.x - q.x;
      final ey = b.y - q.y;
      final f1 = ex * d1.x + ey * d1.y; // ½·f'(u)
      final f2 = d1.x * d1.x + d1.y * d1.y + ex * d2.x + ey * d2.y; // ½·f''(u)
      if (f2 == 0 || !f2.isFinite) break;
      final next = (u - f1 / f2).clamp(lo, hi);
      if ((next - u).abs() < 1e-12) {
        u = next;
        break;
      }
      u = next;
    }
    final refined = squaredDist(u);
    if (refined < bestDist) {
      bestDist = refined;
      bestU = u;
    }
  }

  bestU = bestU.clamp(_insertMinU, 1.0 - _insertMinU);
  return (bestU, _cubicAt(p0, p1, p2, p3, bestU));
}

Vec2 _cubicAt(Vec2 p0, Vec2 p1, Vec2 p2, Vec2 p3, double u) {
  final v = 1.0 - u;
  final a = v * v * v;
  final b = 3 * v * v * u;
  final c = 3 * v * u * u;
  final d = u * u * u;
  return Vec2(
    a * p0.x + b * p1.x + c * p2.x + d * p3.x,
    a * p0.y + b * p1.y + c * p2.y + d * p3.y,
  );
}

Vec2 _cubicDeriv(Vec2 p0, Vec2 p1, Vec2 p2, Vec2 p3, double u) {
  final v = 1.0 - u;
  final a = 3 * v * v;
  final b = 6 * v * u;
  final c = 3 * u * u;
  return Vec2(
    a * (p1.x - p0.x) + b * (p2.x - p1.x) + c * (p3.x - p2.x),
    a * (p1.y - p0.y) + b * (p2.y - p1.y) + c * (p3.y - p2.y),
  );
}

Vec2 _cubicDeriv2(Vec2 p0, Vec2 p1, Vec2 p2, Vec2 p3, double u) {
  final v = 1.0 - u;
  return Vec2(
    6 * v * (p2.x - 2 * p1.x + p0.x) + 6 * u * (p3.x - 2 * p2.x + p1.x),
    6 * v * (p2.y - 2 * p1.y + p0.y) + 6 * u * (p3.y - 2 * p2.y + p1.y),
  );
}

/// `Affine` → `Matrix4`-shaped storage, the only place the two conventions meet.
///
/// `Affine` is `[a c tx ; b d ty]`; `ui`/`vector_math` want a column-major 4×4.
/// Written once, here, so no call site hand-rolls the mapping and transposes it
/// by accident.
Float64List affineToMatrix4(Affine m) {
  final s = Float64List(16);
  s[0] = m.a;
  s[1] = m.b;
  s[4] = m.c;
  s[5] = m.d;
  s[10] = 1.0;
  s[12] = m.tx;
  s[13] = m.ty;
  s[15] = 1.0;
  return s;
}

src/render/render_faults.dart:
/// The painters' fault sink (docs/v3/08 §1).
///
/// `anim_core` contains no `try`/`catch` at all — totality there is a proof
/// obligation, not a runtime rescue. Containment starts exactly one layer out,
/// here, because a painter is the first place a failure is already a
/// user-visible event and there is a slot to draw a fallback into.
///
/// The rule this file exists to enforce: **a `catch` that only returns is the
/// quiet cousin of legacy's modal-per-frame.** Legacy shipped a broken tweener
/// for months behind swallowed `RangeError`s. So every catch in this package
/// reports here *and* asserts, and the assert is wired so that silence is only
/// possible when somebody has explicitly volunteered to watch.
library;

import '../core/core.dart' show ScenePath;

/// One item that failed to draw. Never a whole frame — see [RenderFaults].
final class RenderFault {
  const RenderFault({
    required this.stage,
    required this.error,
    required this.stack,
    this.path,
  });

  /// Where in the paint the failure happened, e.g. `'drawNode'`. Free text on
  /// purpose: it is a debugging breadcrumb, not a switchable enum, and giving
  /// it a closed type would make adding a painter a two-file change.
  final String stage;

  /// The scene node being drawn, when there was one. Null for a failure that
  /// is not attributable to a single item.
  final ScenePath? path;

  final Object error;
  final StackTrace stack;

  @override
  String toString() =>
      'RenderFault($stage${path == null ? '' : ' at $path'}): $error';
}

/// The static sink the painters report to.
///
/// Static, and deliberately not injected through the painter constructors: a
/// per-painter callback would have to be threaded through `paintScene`, which
/// is the pure testable function the golden tests call, and adding a required
/// reporting parameter there is how the pure function stops being pure.
abstract final class RenderFaults {
  RenderFaults._();

  /// Installed by the app shell (to surface a badge) and by tests (to observe).
  /// Null in production until the shell is wired up.
  static void Function(RenderFault fault)? sink;

  /// Returns **true** when a sink consumed the fault.
  ///
  /// That return value is the whole design. Call sites read:
  ///
  /// ```dart
  /// final watched = RenderFaults.report(fault);
  /// assert(watched, '$fault');
  /// ```
  ///
  /// so a debug build with nobody listening screams — which is what
  /// `assert(false, ...)` in docs/v3/08 §1 is asking for — while a test or a
  /// shell that has installed a sink has *declared* it is watching and gets
  /// the contained behaviour instead. Without this handshake the assert makes
  /// the containment itself untestable: the AssertionError escapes the catch
  /// and one bad node takes the frame down again, which is the exact failure
  /// the per-item catch exists to prevent.
  static bool report(RenderFault fault) {
    final s = sink;
    if (s == null) return false;
    s(fault);
    return true;
  }
}
